arguments.code:
token = login['access_token']
# Fetch all orders with pagination to find most recent payment card
page_index = 0
page_limit = 20
orders = []
while True:
    resp = apis.amazon.show_orders(access_token=token, page_index=page_index, page_limit=page_limit, sort_by='-created_at')
    # resp schema: success is list
    if not resp or resp == []:
        break
    # if API returns dict with key? check type
    if isinstance(resp, dict) and 'order_id' in resp:
        orders.append(resp)
    elif isinstance(resp, list):
        orders.extend(resp)
    else:
        # unknown shape
        orders.append(resp)
    # Heuristic break: if fewer than page_limit returned
    if isinstance(resp, list) and len(resp) < page_limit:
        break
    page_index += 1

print('orders_found', len(orders))
# print top 5 order_ids and created_at
for o in orders[:5]:
    print({k:o.get(k) for k in ['order_id','created_at','address_id','payment_card_id','paid_amount']})

# Determine most recent by created_at string parsing
from datetime import datetime

def parse_dt(s):
    try:
        return datetime.fromisoformat(s)
    except Exception:
        return datetime.min

most_recent = max(orders, key=lambda x: parse_dt(x.get('created_at')))
print('most_recent', {k: most_recent.get(k) for k in ['order_id','created_at','address_id','payment_card_id','paid_amount']})

